import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    if not isinstance(search_content, str) and search_content is not None:
        return jsonify({"error": "search_content must be a string"}), 400
    if not isinstance(search_filename, str) and search_filename is not None:
        return jsonify({"error": "search_filename must be a string"}), 400
    if not isinstance(search_dir, str) and search_dir is not None:
        return jsonify({"error": "search_dir must be a string"}), 400

    base_dir = os.path.join('/data', search_dir) if search_dir else '/data'

    if not os.path.isdir(base_dir):
        return jsonify({"error": "search_dir does not exist or is not a directory"}), 400

    matches = []

    for root, _, files in os.walk(base_dir):
        for file in files:
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'rb') as f:
                    content = f.read()
            except (PermissionError, OSError):
                continue

            match = False
            if search_content is not None:
                try:
                    if isinstance(search_content, str):
                        if search_content.encode('utf-8') in content:
                            match = True
                    else:
                        match = False
                except (UnicodeDecodeError, TypeError):
                    match = False
            elif search_filename is not None:
                if file.startswith(search_filename):
                    match = True

            if match:
                matches.append(filepath)

    return jsonify({"files": matches}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
